const MS_PER_DAY = 86400000;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function parseCalendarDate(value) {
  if (
    typeof value !== "string" ||
    value.length !== 10 ||
    !DATE_PATTERN.test(value)
  ) {
    throw new RangeError("Dates must be strings in YYYY-MM-DD form.");
  }

  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));

  // UTC setters avoid timezone effects and Date.UTC's special handling of 0–99.
  const utcDate = new Date(0);
  utcDate.setUTCFullYear(year, month - 1, day);

  if (
    utcDate.getUTCFullYear() !== year ||
    utcDate.getUTCMonth() !== month - 1 ||
    utcDate.getUTCDate() !== day
  ) {
    throw new RangeError("Invalid calendar date.");
  }

  return utcDate.getTime() / MS_PER_DAY;
}

const MIN_DAY = parseCalendarDate("0000-01-01");
const MAX_DAY = parseCalendarDate("9999-12-31");

function dayOfWeek(day) {
  // Day zero is Thursday. Normalize the remainder for dates before 1970.
  return ((day + 4) % 7 + 7) % 7;
}

function isWeekday(day) {
  const weekday = dayOfWeek(day);
  return weekday >= 1 && weekday <= 5;
}

function buildObservedHolidays(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array of calendar dates.");
  }

  const observed = new Set();
  const weekends = [];

  // Reserve every weekday holiday before assigning any weekend holidays.
  for (const holiday of holidays) {
    const day = parseCalendarDate(holiday);
    if (isWeekday(day)) {
      observed.add(day);
    } else {
      weekends.push(day);
    }
  }

  weekends.sort((a, b) => a - b);

  let afterPrevious = -Infinity;

  for (const holiday of weekends) {
    const monday = holiday + (dayOfWeek(holiday) === 6 ? 2 : 1);

    // Initial Mondays are nondecreasing, so previously skipped days stay busy.
    let candidate = Math.max(monday, afterPrevious);
    while (!isWeekday(candidate) || observed.has(candidate)) {
      candidate += 1;
    }

    observed.add(candidate);
    afterPrevious = candidate + 1;
  }

  return Array.from(observed).sort((a, b) => a - b);
}

// Index of the first entry strictly greater than value.
function upperBound(sorted, value) {
  let low = 0;
  let high = sorted.length;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (sorted[middle] <= value) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

function isBusinessDayNumber(day, observed) {
  if (!isWeekday(day)) {
    return false;
  }

  const index = upperBound(observed, day);
  return index === 0 || observed[index - 1] !== day;
}

// Counts business days in (start, end], where start <= end.
function countBusinessDays(start, end, observed) {
  const length = end - start;
  let count = Math.floor(length / 7) * 5;
  const remainder = length % 7;
  const startWeekday = dayOfWeek(start);

  for (let offset = 1; offset <= remainder; offset += 1) {
    const weekday = (startWeekday + offset) % 7;
    if (weekday >= 1 && weekday <= 5) {
      count += 1;
    }
  }

  return (
    count -
    (upperBound(observed, end) - upperBound(observed, start))
  );
}

export function isBusinessDay(date, holidays = []) {
  const day = parseCalendarDate(date);
  const observed = buildObservedHolidays(holidays);
  return isBusinessDayNumber(day, observed);
}

export function addBusinessDays(date, n, holidays = []) {
  const start = parseCalendarDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer.");
  }

  const observed = buildObservedHolidays(holidays);

  if (n === 0 && isBusinessDayNumber(start, observed)) {
    return date;
  }

  const direction = n < 0 ? -1 : 1;
  const target = n === 0 ? 1 : Math.abs(n);
  const maxDistance =
    direction === 1 ? MAX_DAY - start : start - MIN_DAY;

  // Backward walks count [start - distance, start), excluding the start.
  const countAtDistance = (distance) =>
    direction === 1
      ? countBusinessDays(start, start + distance, observed)
      : countBusinessDays(start - distance - 1, start - 1, observed);

  // A valid output must retain a four-digit year.
  if (countAtDistance(maxDistance) < target) {
    throw new RangeError("The result is outside the YYYY-MM-DD date range.");
  }

  // Find the first distance at which the requested business day is reached.
  let low = 1;
  let high = maxDistance;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (countAtDistance(middle) >= target) {
      high = middle;
    } else {
      low = middle + 1;
    }
  }

  const result = start + direction * low;
  return new Date(result * MS_PER_DAY).toISOString().slice(0, 10);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startDay = parseCalendarDate(start);
  const endDay = parseCalendarDate(end);
  const observed = buildObservedHolidays(holidays);

  const count = countBusinessDays(
    Math.min(startDay, endDay),
    Math.max(startDay, endDay),
    observed
  );

  return endDay < startDay && count !== 0 ? -count : count;
}
